"""Virtual path helpers."""


def _check_abs(path):
    if not path.startswith("/"):
        raise ValueError("path must be absolute: %r" % path)


def segments(path):
    _check_abs(path)
    out = []
    for seg in path.split("/"):
        if seg == "" or seg == ".":
            continue
        if seg == "..":
            if out:
                out.pop()
            continue
        out.append(seg)
    return out


def normalize(path):
    return "/" + "/".join(segments(path))


def join(base, *parts):
    _check_abs(base)
    cur = base
    for part in parts:
        if part.startswith("/"):
            cur = part
        else:
            cur = cur + "/" + part
    return normalize(cur)


def is_within(path, root):
    p, r = segments(path), segments(root)
    return len(p) >= len(r) and p[:len(r)] == r


def relative(src, dst):
    a, b = segments(src), segments(dst)
    n = 0
    while n < len(a) and n < len(b) and a[n] == b[n]:
        n += 1
    parts = [".."] * (len(a) - n) + b[n:]
    return "/".join(parts) if parts else "."


def resolve(path, mounts):
    p = segments(path)
    best = None
    for prefix, target in mounts.items():
        pre = segments(prefix)
        if len(pre) <= len(p) and p[:len(pre)] == pre:
            if best is None or len(pre) > len(best[0]):
                best = (pre, target)
    if best is None:
        return normalize(path)
    pre, target = best
    rest = p[len(pre):]
    return join(target, *rest) if rest else normalize(target)

